import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.RQXGjTIX.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),r={name:"guide/changelog.md"};function t(n,e,d,s,c,h){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="_0-2-2" tabindex="-1">0.2.2 <a class="header-anchor" href="#_0-2-2" aria-label="Permalink to &quot;0.2.2&quot;">​</a></h2><h3 id="高容量气体元件" tabindex="-1">高容量气体元件 <a class="header-anchor" href="#高容量气体元件" aria-label="Permalink to &quot;高容量气体元件&quot;">​</a></h3><ul><li>新增 <strong>1M / 4M / 16M / 64M / 256M</strong> 五档元件，总容量 = 字节数 × 1,000 GU；</li><li>使用 MEGA 风格档位强调色，同时保留本模组的青绿色外壳；</li><li>默认配方使用 MEGA Cells 的元件外壳、存储核心和 CCB 气密储罐；</li><li>默认配方带 <code>neoforge:mod_loaded</code> 条件：<strong>只有安装 MEGA Cells 时才加载</strong>；</li><li>新增配置项 <code>recipes.enable_mega_cell_recipes</code>，可移除默认 MEGA 配方，允许数据包提供自定义配方。</li></ul><h3 id="接口与自动化" tabindex="-1">接口与自动化 <a class="header-anchor" href="#接口与自动化" aria-label="Permalink to &quot;接口与自动化&quot;">​</a></h3><ul><li>ME 气体接口新增逐槽设置界面：目标数量、目标压力和传输模式；</li><li>新增<strong>逐槽控制卡</strong>；</li><li>新增<strong>安全卡</strong>（<code>safety_valve_card</code>），危险超压时通过 CCB 真实释放；</li><li>新增<strong>气体压力卡</strong>（<code>gas_pressure_card</code>），安装在 AE2 输入/输出总线上设置目标压力；</li><li>AE2 原生 ME 接口、样板供应器、输入/输出/存储总线重新获得气体支持；</li><li>安装 AE2-JEI-Integration 时，JEI 的 “+” 可把 CCB 气体输入/输出编码进 AE2 处理样板。</li></ul><h3 id="稳定性与文档" tabindex="-1">稳定性与文档 <a class="header-anchor" href="#稳定性与文档" aria-label="Permalink to &quot;稳定性与文档&quot;">​</a></h3><ul><li>修复气体自动合成在保存并重载世界后丢失样板输出的问题；</li><li>新增气体存储元件、ME 气体接口与自动化的 GuideME 页面；</li><li>全部十档气体元件在 GuideME 中按 <strong>G</strong> 可打开对应页面；</li><li>更新气体样本和新升级卡贴图。</li></ul><h2 id="_0-2-1" tabindex="-1">0.2.1 <a class="header-anchor" href="#_0-2-1" aria-label="Permalink to &quot;0.2.1&quot;">​</a></h2><ul><li><strong>JEI 拖拽标记</strong>：安装 JEI 时，把 CCB 的气体 ingredient 或气体虚拟物品拖到配置槽即可标记该槽气体；</li><li>配置槽右键标记现在也支持 CCB 的虚拟气体物品（<code>VirtualGasItems</code>）；</li><li>JEI 是可选依赖，未安装时其余功能不受影响。</li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="me-气体接口重做" tabindex="-1">ME 气体接口重做 <a class="header-anchor" href="#me-气体接口重做" aria-label="Permalink to &quot;ME 气体接口重做&quot;">​</a></h3><ul><li>改为与原版 ME 接口相同的<strong>九组配置槽 + 九组缓存槽</strong>结构； 每槽目标数量 0–64kGU，目标压力 0–16 atm（容器额定 24 atm）； 槽位体积按 <code>目标数量 / 目标压力</code> 推导，装满时压力恰好等于目标压力。</li><li>默认<strong>全部双向</strong>；新增<strong>逐槽控制卡</strong>，安装后每槽可独立选择输入 / 输出 / 双向 / 关闭； 移除卡片后回到统一双向，配置保留。</li><li>升级槽从 4 个增加到 <strong>6 个</strong>（速度卡 ≤4、逐槽控制卡 1、安全卡 1）。</li><li>新增<strong>安全卡</strong>：压力达到 20 atm 时通过 CCB 的 <code>GasReleaseService</code> 真实释放气体 （径向 <code>OVERFLOW</code>，含环境效果/实体推动），只有释放成功才扣除槽内气体。</li><li>气体标记：新增 <code>gas_sample</code> 气体样本物品与 <code>gas_id</code> 数据组件； 支持手持气体样本/气体容器右键配置槽标记；配置槽也接受 AE2 包裹气体物品。</li><li>旧版 8 kL 缓冲罐中的气体在升级时自动转入<strong>第一个空槽</strong>；九槽都满时记录日志并丢弃。</li><li>移除 0.1.x 给 <code>ae2:interface</code> 添加的旧气体缓存兼容；0.2.2 已用新的适配器恢复原版接口的气体能力。</li><li>废弃 <code>gas_interface.bufferVolumeLiters</code> / <code>supplyPressureKpa</code> / <code>transferRate</code> / <code>energyPerKiloGasUnit</code> 配置项；仅保留 <code>gas_interface.idlePower</code>。</li></ul><h3 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to &quot;已知限制&quot;">​</a></h3><ul><li>输入/输出总线的逐部件目标压力在 0.2.0 尚未实现；0.2.2 由气体压力卡补齐；</li><li>JEI 拖拽标记在 0.2.1 接入；</li><li>气体 P2P、气体存储元件、总线/存储总线/样板供应器的气体支持保持不变。</li></ul><h2 id="_0-1-1" tabindex="-1">0.1.1 <a class="header-anchor" href="#_0-1-1" aria-label="Permalink to &quot;0.1.1&quot;">​</a></h2><ul><li>256×256 模组图标；</li><li>新的气体接口方块贴图；</li><li>0.1.0 的发布修正。</li></ul><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><ul><li>首个版本：气体存储元件（1k–256k）、ME 气体接口、气体 P2P 隧道、 元件升级卡、GuideME 教程。</li></ul>',19)])])}const _=a(r,[["render",t]]);export{g as __pageData,_ as default};
